7	export const EntirePlugin: Plugin = async ({ directory }) => {
8	  // Track seen user messages to fire turn-start only once per message
9	  const seenUserMessages = new Set<string>()
10	  // Track current session ID for message events (which don't include sessionID)
11	  let currentSessionID: string | null = null
12	  // Track the model used by the most recent assistant message
13	  let currentModel: string | null = null
14	  // In-memory store for message metadata (role, tokens, etc.)
15	  const messageStore = new Map<string, any>()
16	  // One-time model-context injection captured from the turn-start hook's stdout,
17	  // applied on the next LLM call via experimental.chat.system.transform.
18	  let pendingInjection: string | null = null
19	
20	  /**
21	   * Build the shell command for a hook invocation.
22	   * Uses sh -c so the command is guarded by a `command -v` probe: when the
23	   * entire binary is not on PATH the hook exits 0 rather than failing the
24	   * surrounding OpenCode operation.
25	   */
26	  function hookCmd(hookName: string): string[] {
27	    return ["sh", "-c", `if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks opencode ${hookName}`]
28	  }
29	
30	  /**
31	   * Pipe JSON payload to an entire hooks command (async).
32	   * Errors are logged but never thrown — plugin failures must not crash OpenCode.
33	   */
34	  async function callHook(hookName: string, payload: Record<string, unknown>) {
35	    try {
36	      const json = JSON.stringify(payload)
37	      const proc = Bun.spawn(hookCmd(hookName), {
38	        cwd: directory,
39	        stdin: new Blob([json + "\n"]),
40	        stdout: "ignore",
41	        stderr: "ignore",
42	      })
43	      await proc.exited
44	    } catch {
45	      // Silently ignore — plugin failures must not crash OpenCode
46	    }
47	  }
48	
49	  /**
50	   * Synchronous variant for hooks that must complete before subsequent agent work
51	   * or process exit. `turn-start` must finish initializing session state before a
52	   * fast mid-turn commit can hit git hooks, and `turn-end` / `session-end` must
53	   * finish before `opencode run` tears down its event loop.
54	   */
55	  function callHookSync(hookName: string, payload: Record<string, unknown>) {
56	    try {
57	      const json = JSON.stringify(payload)
58	      Bun.spawnSync(hookCmd(hookName), {
59	        cwd: directory,
60	        stdin: new TextEncoder().encode(json + "\n"),
61	        stdout: "ignore",
62	        stderr: "ignore",
63	      })
64	    } catch {
65	      // Silently ignore — plugin failures must not crash OpenCode
66	    }
67	  }
68	
69	  // parseInjectedContext scans a hook's stdout for Entire's injection envelope
70	  // ({"inject_context":"..."}) and returns the text to inject, or null.
71	  function parseInjectedContext(stdout: string): string | null {
72	    if (!stdout) return null
73	    for (const line of stdout.split("\n")) {
74	      const trimmed = line.trim()
75	      if (!trimmed.startsWith("{")) continue
76	      try {
77	        const parsed = JSON.parse(trimmed) as { inject_context?: unknown }
78	        if (typeof parsed.inject_context === "string" && parsed.inject_context.length > 0) {
79	          return parsed.inject_context
80	        }
81	      } catch {
82	        // not our envelope — ignore
83	      }
84	    }
85	    return null
86	  }
87	
88	  // fireTurnStart fires turn-start synchronously (state must be ready before
89	  // mid-turn commits) and stashes any model-context injection emitted on stdout
90	  // for experimental.chat.system.transform to apply. Entire emits the injection
91	  // at most once per session, so pendingInjection is set on the first turn only.
92	  function fireTurnStart(payload: Record<string, unknown>) {
93	    try {
94	      const json = JSON.stringify(payload)
95	      const proc = Bun.spawnSync(hookCmd("turn-start"), {
96	        cwd: directory,
97	        stdin: new TextEncoder().encode(json + "\n"),
98	        stdout: "pipe",
99	        stderr: "ignore",
100	      })
101	      const out = proc.stdout ? proc.stdout.toString() : ""
102	      const injected = parseInjectedContext(out)
103	      if (injected) pendingInjection = injected
104	    } catch {
105	      // Silently ignore — plugin failures must not crash OpenCode
106	    }
107	  }
108	
109	  function resetSessionTracking(sessionID: string) {
110	    if (currentSessionID === sessionID) {
111	      return false
112	    }
113	    seenUserMessages.clear()
114	    messageStore.clear()
115	    currentModel = null
116	    currentSessionID = sessionID
117	    // Drop any turn-start injection captured for the prior session so it
118	    // can't leak into the new session's system prompt.
119	    pendingInjection = null
120	    return true
121	  }
122	
123	  return {
124	    // Apply the one-time Entire context injection captured at turn-start by
125	    // appending it to the system prompt for this LLM call.
126	    "experimental.chat.system.transform": async (_input: unknown, output: { system: string[] }) => {
127	      if (pendingInjection && Array.isArray(output.system)) {
128	        output.system.push(pendingInjection)
129	        pendingInjection = null
130	      }
131	    },
132	    event: async ({ event }) => {
133	      try {
134	        switch (event.type) {
135	          case "session.created": {
136	            const session = (event as any).properties?.info
